import React, { useEffect, useState } from "react";
import type { HeadFC, PageProps } from "gatsby";
import SEO from "../../../components/seo";
import rawData from "../../../data/data.json";

const companyData = {
  companyName: rawData.name,
  address: rawData.address,
  city: rawData.city,
  province: rawData.province,
  country: "Canada",
  phone: rawData.phone,
  email: rawData.email,
  instagram: rawData.instagram,
  facebook: rawData.facebook,
  linkedin: "",
  postalCode: rawData.postalCode,
  url: rawData.url,
  whatsapp: "",
  menu: rawData.menu,
};
import type { Activity, Itinerary, ItineraryDay } from "../../../features/admin/types";
import { getItineraryByToken } from "../../../sessionServices/itineraries/sharedAccessService";
import { listDaysByItinerary } from "../../../sessionServices/itineraries/itineraryDaysService";
import { listActivitiesByItinerary } from "../../../sessionServices/itineraries/activitiesService";
import images from "../../../images";
import { FaCalendarDays, FaMapLocationDot } from "react-icons/fa6";
import { BsPeopleFill } from "react-icons/bs";

type ItineraryWithId = Itinerary & { id: string };
type DayWithId = ItineraryDay & { id: string };
type ActivityWithId = Activity & { id: string };

export default function SharedItineraryPage({ params }: PageProps) {
  const token = params["token"];

  const [itinerary, setItinerary] = useState<ItineraryWithId | null>(null);
  const [days, setDays] = useState<DayWithId[]>([]);
  const [activities, setActivities] = useState<ActivityWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    async function load() {
      const data = await getItineraryByToken(token) as ItineraryWithId | null;
      if (!data) { setNotFound(true); setLoading(false); return; }
      const [daysData, actsData] = await Promise.all([
        listDaysByItinerary(data.id),
        listActivitiesByItinerary(data.id),
      ]);
      setItinerary(data);
      document.title = `${data.title} — Jenny Adventures`;
      setDays([...daysData].sort((a, b) => (a.date as { toMillis: () => number }).toMillis() - (b.date as { toMillis: () => number }).toMillis()));
      setActivities(actsData);
      setLoading(false);
    }
    load();
  }, [token]);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (notFound || !itinerary) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4">
        <div className="text-center">
          <p className="text-5xl font-bold text-gray-200">404</p>
          <h1 className="mt-4 text-lg font-semibold text-gray-800">Itinerary not found</h1>
          <p className="mt-2 text-sm text-gray-500">
            This link may have expired or been revoked. Please contact your travel agent.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm">

        <div className="mx-auto max-w-2xl px-4 py-6">
          <div className={styles.logoContainer}>
            <img
              src={images.logo.src}
              alt={images.logo.alt}
              className={styles.logo}
            />
            <p className="block text-main h1_mobile sm:h1_desk truncate ml-2 pr-0 sm:pr-2 py-1">
              Jenny Adventures
            </p>
          </div>
          <h2 className="mt-1 text-2xl font-semibold text-gray-900">{itinerary.title}</h2>
          <p className="mt-1 text-sm text-gray-500">{itinerary.summary}</p>
          <div className="mt-3 flex flex-wrap gap-4 text-xs text-gray-500">
            <span className="flex gap-1"><FaMapLocationDot className="text-main text-lg self-center" /> {itinerary.destinationCities.join(", ") || "—"}</span>
            <span className="flex gap-1"><FaCalendarDays className="text-main text-lg self-center" /> {formatDate(itinerary.startDate)} – {formatDate(itinerary.endDate)}</span>
            <span className="flex gap-1"><BsPeopleFill className="text-main text-lg self-center" /> {itinerary.travelerCount} traveler{itinerary.travelerCount !== 1 ? "s" : ""}</span>
          </div>
        </div>
      </header>

      {/* Days */}
      <main className="mx-auto max-w-2xl space-y-6 px-4 py-8">
        {days.length === 0 ? (
          <p className="text-center text-sm text-gray-400">Your itinerary is being prepared.</p>
        ) : (
          days.map((day, index) => {
            const dayActivities = activities
              .filter((a) => a.itineraryDayId === day.id)
              .sort((a, b) => (a.startTime ?? "").localeCompare(b.startTime ?? ""));

            return (
              <div key={day.id} className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-gray-100">
                {/* Day header */}
                <div className="flex items-center gap-3 bg-gray-900 px-5 py-3">
                  <span className="flex h-7 w-7 items-center justify-center rounded-full bg-white text-xs font-bold text-gray-900">
                    {index + 1}
                  </span>
                  <div>
                    <p className="text-sm font-semibold text-white">
                      {day.city}{day.title ? ` — ${day.title}` : ""}
                    </p>
                    <p className="text-xs text-gray-400">{formatDate(day.date)}</p>
                  </div>
                </div>

                {/* Day notes */}
                {day.notes && (
                  <div className="border-b border-gray-100 bg-amber-50 px-5 py-2">
                    <p className="text-xs text-amber-800">{day.notes}</p>
                  </div>
                )}

                {/* Activities */}
                {dayActivities.length === 0 ? (
                  <p className="px-5 py-4 text-sm text-gray-400">No activities scheduled.</p>
                ) : (
                  <div className="divide-y divide-gray-100">
                    {dayActivities.map((act) => (
                      <div key={act.id} className="px-5 py-4">
                        <div className="flex items-start gap-3">
                          {act.startTime && (
                            <span className="mt-0.5 shrink-0 font-mono text-xs text-gray-400">
                              {act.startTime}
                            </span>
                          )}
                          <div className="flex-1 space-y-1">
                            <div className="flex flex-wrap items-center gap-2">
                              <p className="text-sm font-semibold text-gray-900">{act.name}</p>
                              {act.category && (
                                <span className="rounded-full bg-gray-100 px-2 py-0.5 text-xs text-gray-500">
                                  {act.category}
                                </span>
                              )}
                              {act.durationMinutes && (
                                <span className="text-xs text-gray-400">
                                  {formatDuration(act.durationMinutes)}
                                </span>
                              )}
                            </div>
                            <p className="text-sm text-gray-600">{act.description}</p>
                            {act.location && (
                              <p className="text-xs text-gray-400">📍 {act.location}</p>
                            )}
                            {act.observations && (
                              <p className="text-xs italic text-gray-400">{act.observations}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })
        )}

        <p className="pb-4 text-center text-xs text-gray-400">
          Prepared by Jenny Adventures · {itinerary.destinationCities.join(", ")}
        </p>
      </main>
    </div>
  );
}

function formatDuration(minutes: number): string {
  if (minutes < 60) return `${minutes} min`;
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return m > 0 ? `${h}h ${m}min` : `${h}h`;
}

function formatDate(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toLocaleDateString("en-CA", {
      weekday: "short", month: "short", day: "numeric", timeZone: "UTC",
    });
  } catch {
    return "—";
  }
}

const styles = {
    logoContainer: "flex justify-center items-center",
    logo: "h-[60px]",
};

export const Head: HeadFC = () => (
  <SEO
    data={companyData}
    title="Your Itinerary — Jenny Adventures"
    description="View your personalized travel itinerary prepared by Jenny Adventures."
    pathname="/app/itinerary"
    noindex
  />
);